import json,urllib.request,subprocess,datetime
r={'at':datetime.datetime.now().isoformat(timespec='seconds')}
for path in ('/api/health','/api/operator-lifecycle','/api/supervisor-watchdog/managed-chats?inspect=0'):
 try:
  with urllib.request.urlopen('http://127.0.0.1:17448'+path,timeout=3) as f:d=json.load(f)
  if path=='/api/health':r['health']={k:d.get(k) for k in ('state','ok','reasons','blockers','assignmentQueue','codeReload','startedAt')}
  elif path=='/api/operator-lifecycle':r['lifecycle']={k:d.get(k) for k in ('mode','revision','queuePaused','quiescence')}
  else:r['chats']={'n':len(d.get('chats',[])),'status':[{k:z.get(k) for k in ('name','status','highMode','generating','openTabs')} for z in d.get('chats',[])[:12]]}
 except Exception as e:r[path]={'error':type(e).__name__}
try:
 g=subprocess.run(['git.exe','-C',r'E:\WebAIBridge','rev-parse','HEAD'],capture_output=True,text=True,timeout=4)
 r['head']=g.stdout.strip() if g.returncode==0 else 'git_error'
except Exception as e:r['head']='exception:'+type(e).__name__
print(json.dumps(r,ensure_ascii=True,separators=(',',':'))[:8500])
